const test = require('node:test');
const assert = require('node:assert/strict');
const { clampPage } = require('../gallery.cjs');
test('last page is the total number of pages', () => {
  for (const [requested, totalPages, expected] of [[7,4,4],[4,4,4],[3,4,3],[1,4,1],[2,1,1],[1,1,1],[1,0,0],[9,0,0],[20,12,12]]) {
    assert.equal(clampPage(requested, totalPages), expected, `${requested}/${totalPages}`);
  }
});

